  ('10000000-0000-0000-0000-000000000001', 'scholarship', 'Government of Rwanda Bilateral Higher Education Scholarships', 'Higher Education Council (HEC)', 'Fully funded foreign bilateral scholarships awarded annually to outstanding Rwandan university students for undergraduate and postgraduate studies abroad.', '["Full tuition & living allowance", "Bilateral partner countries", "Competitive national selection"]'::jsonb, 'https://hec.gov.rw/scholarships/bilateral', '2026-11-15', false, '2026-08-01', '2027-09-01', 'abroad', 'Host partner countries', 'full', array['bachelor','master','phd'], array['STEM','Health Sciences','Engineering'], '{"rwandans_eligible": true, "nationalities": ["Rwandan"], "min_gpa": {"value": 3.5, "scale": 4.0}, "max_age": 30}'::jsonb, true, '["Attain minimum GPA 3.5/4.0", "Obtain official university transcripts", "Secure academic recommendation letters"]'::jsonb, 'published', 0.98, 'c_hash_001', now(), now(), now()),

  ('10000000-0000-0000-0000-000000000002', 'internship', 'RDB National Youth Professional Internship Programme', 'Rwanda Development Board (RDB)', 'Structured 6-to-12 month professional placement placing university graduates into high-growth private sector firms and public sector agencies.', '["Monthly living stipend", "6 to 12 months duration", "Industry mentorship"]'::jsonb, 'https://rdb.rw/opportunities/internships', '2026-10-31', false, '2026-06-01', '2027-01-15', 'rwanda', 'Kigali & Secondary Cities, Rwanda', 'partial', array['bachelor','diploma'], array['Business','Information Technology','Tourism','Finance'], '{"rwandans_eligible": true, "nationalities": ["Rwandan"], "max_age": 30}'::jsonb, false, null, 'published', 0.95, 'c_hash_002', now(), now(), now()),

  ('10000000-0000-0000-0000-000000000003', 'fellowship', 'iAccelerator Youth Health and Entrepreneurship Innovation Grant', 'Imbuto Foundation', 'Mentorship, bootcamps, and seed capital for young Rwandan university entrepreneurs building digital and community health solutions.', '["Up to 10,000 USD seed grant", "4-month business acceleration", "Expert executive mentorship"]'::jsonb, 'https://imbutofoundation.org/programmes/iaccelerator', '2026-11-20', false, '2026-08-15', '2027-02-01', 'rwanda', 'Kigali, Rwanda', 'full', array['bachelor','master','diploma'], array['Public Health','Computer Science','Entrepreneurship'], '{"rwandans_eligible": true, "nationalities": ["Rwandan"], "max_age": 30}'::jsonb, false, null, 'published', 0.95, 'c_hash_003', now(), now(), now()),

  ('10000000-0000-0000-0000-000000000004', 'fellowship', 'Jasiri Talent Investor Cohort 6', 'Jasiri (Allan & Gill Gray Philanthropy)', 'Fully funded 13-month venture creation program providing aspiring entrepreneurs with monthly stipend, co-founder matching, and seed funding.', '["Fully funded with monthly stipend", "Seed funding up to 40,000 USD", "Residential bootcamp"]'::jsonb, 'https://jasiri.org/talent-investor', '2026-10-15', false, '2026-07-01', '2027-01-10', 'mixed', 'Kigali, Rwanda & Nairobi, Kenya', 'full', array['bachelor','master'], array['All Fields','Technology','Business'], '{"rwandans_eligible": true, "nationalities": ["Rwandan","Kenyan","Ethiopian"], "max_age": 32}'::jsonb, false, null, 'published', 0.97, 'c_hash_004', now(), now(), now()),

  ('10000000-0000-0000-0000-000000000005', 'scholarship', 'Master of Science in Global Health Delivery (MGHD) Scholarship', 'University of Global Health Equity (UGHE)', 'Comprehensive merit and need-based scholarship covering full tuition, housing, and living expenses at UGHE Butaro Campus.', '["Full tuition, room & board", "2-year residential master degree", "Field rotations across Rwanda"]'::jsonb, 'https://ughe.org/admissions/scholarships/', '2026-11-30', false, '2026-06-01', '2027-09-01', 'rwanda', 'Butaro, Burera District, Rwanda', 'full', array['master'], array['Medicine','Public Health','Nursing'], '{"rwandans_eligible": true, "nationalities": ["Rwandan","African countries"], "min_gpa": {"value": 3.2, "scale": 4.0}, "work_experience_years": 1}'::jsonb, true, '["Maintain GPA above 3.2/4.0", "Acquire at least 1 year clinical or community health experience", "Draft personal statement on health equity in Africa"]'::jsonb, 'published', 0.98, 'c_hash_005', now(), now(), now()),

  ('10000000-0000-0000-0000-000000000006', 'scholarship', 'Mastercard Foundation Scholars Program at CMU-Africa', 'Carnegie Mellon University Africa', 'Full financial coverage including tuition, health insurance, living stipend, and travel for master programs in engineering and artificial intelligence.', '["100% full funding & monthly stipend", "MS in Information Technology or MS in Electrical & Computer Engineering", "Global CMU degree"]'::jsonb, 'https://africa.engineering.cmu.edu/admissions/financial-aid/index.html', '2026-12-15', false, '2026-07-01', '2027-08-20', 'rwanda', 'Kigali Innovation City, Rwanda', 'full', array['master'], array['Computer Science','Information Technology','Electrical Engineering'], '{"rwandans_eligible": true, "nationalities": ["Rwandan","African countries"], "min_gpa": {"value": 3.3, "scale": 4.0}}'::jsonb, true, '["Keep undergraduate GPA above 3.3/4.0", "Review calculus, linear algebra, and data structures", "Prepare portfolio of software or hardware engineering projects"]'::jsonb, 'published', 0.99, 'c_hash_006', now(), now(), now()),

  ('10000000-0000-0000-0000-000000000007', 'scholarship', 'Chevening Master Scholarships (UK)', 'UK Foreign, Commonwealth & Development Office (FCDO)', 'The UK governments flagship global scholarship programme offering full funding for a one-year masters degree at any UK university.', '["100% full university tuition", "Monthly living allowance in UK", "Economy return airfare & visa fees"]'::jsonb, 'https://www.chevening.org/scholarships/guidance/', '2026-11-04', false, '2026-09-12', '2027-09-15', 'abroad', 'United Kingdom', 'full', array['master'], array['All Disciplines','Public Policy','Economics','Climate Change','Law'], '{"rwandans_eligible": true, "nationalities": ["Rwandan"], "min_gpa": {"value": 3.0, "scale": 4.0}, "work_experience_years": 2}'::jsonb, true, '["Accumulate at least 2,800 hours (2 years) of work or volunteer experience", "Draft 4 required essays", "Research and select 3 distinct eligible UK Masters courses"]'::jsonb, 'published', 0.99, 'c_hash_007', now(), now(), now()),

  ('10000000-0000-0000-0000-000000000008', 'scholarship', 'Commonwealth Masters & PhD Scholarships', 'Commonwealth Scholarship Commission in the UK', 'Fully funded postgraduate scholarships for talented individuals from Commonwealth developing countries who could not otherwise afford UK study.', '["Full tuition fees paid", "Airfare to and from UK", "Living stipend & thesis grant"]'::jsonb, 'https://cscuk.fcdo.gov.uk/apply/masters-scholarships/', '2026-10-15', false, '2026-09-01', '2027-09-20', 'abroad', 'United Kingdom', 'full', array['master','phd'], array['Science & Technology','Health Systems','Global Prosperity'], '{"rwandans_eligible": true, "nationalities": ["Rwandan"], "min_gpa": {"value": 3.3, "scale": 4.0}}'::jsonb, true, '["Maintain upper second class honors (GPA 3.3/4.0+)", "Align study plan with UN Sustainable Development Goals in Rwanda", "Seek nomination via national nominating agency (HEC)"]'::jsonb, 'published', 0.98, 'c_hash_008', now(), now(), now()),

  ('10000000-0000-0000-0000-000000000009', 'scholarship', 'DAAD In-Country / In-Region Postgraduate Scholarships', 'German Academic Exchange Service (DAAD)', 'Postgraduate scholarships supporting masters and PhD studies in Sub-Saharan Africa across partner universities in Kenya, Uganda, Tanzania, and Rwanda.', '["Tuition subsidy and monthly stipend", "Research allowance & study visit to Germany", "Health insurance provided"]'::jsonb, 'https://www.daad-kenya.org/en/find-funding/scholarships-for-sub-saharan-africa/', '2026-11-21', false, '2026-08-01', '2027-09-01', 'africa', 'Sub-Saharan Africa', 'full', array['master','phd'], array['Natural Sciences','Engineering','Mathematics','Agriculture'], '{"rwandans_eligible": true, "nationalities": ["Rwandan","Sub-Saharan African countries"], "min_gpa": {"value": 3.2, "scale": 4.0}}'::jsonb, true, '["Attain minimum GPA 3.2/4.0", "Obtain university admission to a designated DAAD regional partner programme", "Draft a research proposal"]'::jsonb, 'published', 0.97, 'c_hash_009', now(), now(), now()),

