values
  ('20000000-0000-0000-0000-000000000001', 'HEC Issues New Accreditation Standards for University Degree Programmes', 'The Higher Education Council has released revised accreditation requirements focusing on digital infrastructure, faculty research output, and industry internship integration across all universities in Rwanda.', 'https://hec.gov.rw/news-updates/accreditation-standards-2026', '2026-09-21T10:00:00.000Z', 'policy', 0.95, 'published'),
  ('20000000-0000-0000-0000-000000000002', 'BRD and MINEDUC Disburse Second Semester Student Loan Allocations', 'The Development Bank of Rwanda and the Ministry of Education have processed living stipends and tuition disbursements for over 45,000 enrolled university loan beneficiaries.', 'https://www.brd.rw/news/education-loans-disbursement-update', '2026-09-20T08:30:00.000Z', 'funding', 0.98, 'published'),
  ('20000000-0000-0000-0000-000000000003', 'University of Rwanda Launches Modern Artificial Intelligence Research Lab at Gikondo', 'UR has inaugurated a high-performance computing laboratory at the African Centre of Excellence in Data Science to support postgraduate research in machine learning and natural language processing.', 'https://ur.ac.rw/?-AI-Lab-Inauguration-Gikondo-', '2026-09-18T14:00:00.000Z', 'universities', 0.92, 'published'),
  ('20000000-0000-0000-0000-000000000004', 'Ministry of ICT Partners with Tech Companies to Expand Graduate Tech Apprenticeships', 'MINICT has formalized partnerships with 20 leading software and fintech companies in Kigali to create 1,200 guaranteed one-year apprenticeships for computer science graduates.', 'https://www.minict.gov.rw/news/graduate-tech-apprenticeships-partnership', '2026-09-17T09:15:00.000Z', 'careers', 0.94, 'published'),
  ('20000000-0000-0000-0000-000000000005', 'RDB Reports 24% Increase in University Student Placements via Professional Internship Scheme', 'Rwanda Development Board labor market survey indicates that 2,800 university graduates secured long-term private sector jobs following their subsidized 6-month internships.', 'https://rdb.rw/news/internship-placement-report-2026', '2026-09-15T11:00:00.000Z', 'careers', 0.91, 'published')
